	"inventoryportal/view/App.view.xml":'<mvc:View\n    controllerName="inventoryportal.controller.App"\n    xmlns:mvc="sap.ui.core.mvc"\n    xmlns:f="sap.f"><f:FlexibleColumnLayout\n            id="fcl"\n            layout="OneColumn"/></mvc:View>',
	"inventoryportal/view/Detail.view.xml":'<mvc:View\n    controllerName="inventoryportal.controller.Detail"\n    xmlns:mvc="sap.ui.core.mvc"\n    xmlns="sap.m"\n    xmlns:form="sap.ui.layout.form"><Page\n        title="{i18n>productDetails}"\n        busy="{view>/busy}"\n        busyIndicatorDelay="0"\n        showNavButton="true"\n        navButtonPress=".onNavBack"><headerContent><Button\n                icon="sap-icon://edit"\n                text="{i18n>edit}"\n                press=".onEdit" /><Button\n                icon="sap-icon://shipping-status"\n                text="{i18n>reorder}"\n                press=".onReorder" /><Button\n                icon="sap-icon://delete"\n                text="{i18n>delete}"\n                type="Reject"\n                press=".onDelete" /></headerContent><content><ObjectHeader\n                title="{products>name}"\n                icon="{products>imageUrl}"\n                number="{\n                    parts: [\n                        \'products>price\',\n                        \'products>currency\'\n                    ],\n                    formatter: \'.formatter.formatCurrency\'\n                }"><firstStatus><ObjectStatus\n                        text="{\n                            parts: [\n                                \'products>stock\',\n                                \'products>reorderThreshold\'\n                            ],\n                            formatter: \'.formatter.getStockStatus\'\n                        }"\n                        state="{\n                            parts: [\n                                \'products>stock\',\n                                \'products>reorderThreshold\'\n                            ],\n                            formatter: \'.formatter.getStockState\'\n                        }"\n                        icon="{\n                            parts: [\n                                \'products>stock\',\n                                \'products>reorderThreshold\'\n                            ],\n                            formatter: \'.formatter.getStockIcon\'\n                        }" /></firstStatus><attributes><ObjectAttribute\n                        title="{i18n>category}"\n                        text="{products>category}" /><ObjectAttribute\n                        title="{i18n>sku}"\n                        text="{products>sku}" /></attributes></ObjectHeader><form:SimpleForm\n                editable="false"\n                layout="ResponsiveGridLayout"\n                title="{i18n>productInformation}"\n                class="sapUiResponsiveMargin"><Label text="{i18n>description}" /><Text text="{products>description}" /><Label text="{i18n>supplier}" /><Text text="{products>supplier}" /><Label text="{i18n>warehouse}" /><Text text="{products>warehouse}" /><Label text="{i18n>stock}" /><Text text="{products>stock}" /><Label text="{i18n>reorderThreshold}" /><Text text="{products>reorderThreshold}" /><Label text="{i18n>lastUpdated}" /><Text\n                    text="{\n                        path: \'products>lastUpdated\',\n                        formatter: \'.formatter.formatDate\'\n                    }" /></form:SimpleForm></content></Page></mvc:View>\n',
	"inventoryportal/view/List.view.xml":'<mvc:View\n    controllerName="inventoryportal.controller.List"\n    xmlns:mvc="sap.ui.core.mvc"\n    xmlns="sap.m"><Page\n        title="{i18n>productList}"\n        busy="{view>/busy}"\n        busyIndicatorDelay="0"><headerContent><SearchField\n                width="20rem"\n                placeholder="{i18n>searchProducts}"\n                liveChange=".onSearch" /></headerContent><content><List\n                id="productList"\n                items="{products>/products}"\n                mode="SingleSelectMaster"\n                itemPress=".onItemPress"\n                updateFinished=".onListUpdateFinished"\n                noDataText="{i18n>noProducts}"><headerToolbar><OverflowToolbar><Title\n                            text="{= ${i18n>productsLabel} + \' (\' + ${view>/visibleCount} + \')\' }" /><ToolbarSpacer /><Button\n                            icon="sap-icon://add"\n                            text="{i18n>addProduct}"\n                            press=".onAddProduct" /><Button\n                            icon="sap-icon://sort"\n                            text="{i18n>sort}"\n                            press=".onOpenSort" /><Button\n                            icon="sap-icon://filter"\n                            text="{i18n>filter}"\n                            press=".onOpenFilter" /><Button\n                            icon="sap-icon://group-2"\n                            text="{i18n>group}"\n                            press=".onOpenGroup" /></OverflowToolbar></headerToolbar><items><ObjectListItem\n                        title="{products>name}"\n                        number="{\n                            parts: [\n                                \'products>price\',\n                                \'products>currency\'\n                            ],\n                            formatter: \'.formatter.formatCurrency\'\n                        }"\n                        type="Navigation"><firstStatus><ObjectStatus\n                                text="{\n                                    parts: [\n                                        \'products>stock\',\n                                        \'products>reorderThreshold\'\n                                    ],\n                                    formatter: \'.formatter.getStockStatus\'\n                                }"\n                                state="{\n                                    parts: [\n                                        \'products>stock\',\n                                        \'products>reorderThreshold\'\n                                    ],\n                                    formatter: \'.formatter.getStockState\'\n                                }"\n                                icon="{\n                                    parts: [\n                                        \'products>stock\',\n                                        \'products>reorderThreshold\'\n                                    ],\n                                    formatter: \'.formatter.getStockIcon\'\n                                }" /></firstStatus><attributes><ObjectAttribute\n                                text="{products>category}" /></attributes></ObjectListItem></items></List></content></Page></mvc:View>\n',
	"inventoryportal/view/NotFound.view.xml":'<mvc:View\n    controllerName="inventoryportal.controller.NotFound"\n    xmlns:mvc="sap.ui.core.mvc"\n    xmlns="sap.m"><Page\n        title="{i18n>notFoundTitle}"><content><VBox\n                alignItems="Center"\n                justifyContent="Center"\n                class="sapUiLargeMargin"><Title\n                    text="{i18n>notFoundMessage}"\n                    level="H2" /><Button\n                    text="{i18n>backToProducts}"\n                    press=".onNavBack"\n                    class="sapUiMediumMarginTop" /></VBox></content></Page></mvc:View>\n'
